/**
 * A sandbox as a record: its state and why, its settings in force, how to reach it, its usage.
 *
 * States, idle and wake: RUNNING lives in its server's memory, PAUSED on its server's disk,
 * STOPPED in object storage. PAUSED keeps memory, processes and disk, and its place on its server:
 * it resumes where it was, never refused for room. STOPPED is a shut-down sandbox: its disk stays,
 * its processes ended, and it starts again when it resumes, its files as it left them. A sandbox
 * stopped by a CRASH (its VM failed, its server ran out of memory or of disk space, or it did not
 * start: {@link StateReason}) starts again only by
 * {@link Sandboxes.resumeSandbox | resumeSandbox}, never by a call into it.
 *
 * A sandbox is idle while nothing happens in it: no call or open stream of SandboxRuntimeService,
 * no open link, SSH session or request to a port, no agent turn running, and no command running
 * that was started with keepAwake. Its lifecycle's three timers run on that one clock (Lifecycle):
 * idle pauseAfterIdleSeconds, a RUNNING sandbox pauses; idle stopAfterIdleSeconds, a RUNNING or
 * PAUSED one stops, and one whose stop comes no later than its pause stops without pausing; idle
 * deleteAfterIdleSeconds, one in any state is deleted, for a sandbox that should cost no storage
 * once done. Idle a minute or more, a RUNNING one may pause sooner, whatever its lifecycle, when
 * its server's memory runs short (IDLE, "paused early: its server's memory ran short").
 *
 * Any call of SandboxRuntimeService, SSH login or request to a port first resumes a PAUSED
 * sandbox, on its server. A STOPPED one wakes so only when its lifecycle says wakeWhenStopped,
 * stopped by a call or by its timer, for a project that wakes now and then, a webhook's; its vCPUs
 * then count while it is STOPPED (Limits.vcpus), so turning it on for a STOPPED sandbox is refused
 * past the limit, and turning it off frees them. Without it such a call is FAILED_PRECONDITION +
 * Stopped, a request to a port is answered 503 "stopped: resume it", and only
 * {@link Sandboxes.resumeSandbox | resumeSandbox} starts it. A wake runs on the sandbox's own
 * server: a PAUSED one keeps its place there and is never refused for room; a STOPPED one without
 * room for it is UNAVAILABLE + {@link NoCapacity}, and
 * {@link Sandboxes.resumeSandbox | resumeSandbox} may start it elsewhere. Of SandboxService, only
 * {@link Sandboxes.resumeSandbox | resumeSandbox} resumes one.
 *
 * A stopped sandbox's disk is copied to object storage a minute after it stops, and its server
 * lets its own copy go when it needs the room: its next start fetches the disk whole first, about
 * 10 s a GiB of what it holds of its own. {@link Sandboxes.resumeSandbox | resumeSandbox} waits up
 * to 45 s for it, then answers the sandbox STOPPED with how far the fetch is (restore), which goes
 * on and starts it; a call into it, an SSH login or a request to a port is UNAVAILABLE + Restoring
 * meanwhile (HTTP 503 with the same words).
 *
 * A server's disk holds only what its sandboxes use. When it runs short, the server stops the
 * PAUSED sandboxes idle the longest ahead of their lifecycles (IDLE, "stopped early: its server's
 * disk ran short"), and a pause is a stop meanwhile ("stopped instead of paused"); when it runs
 * out, it stops the RUNNING sandbox whose disk grew most (CRASH, "its server ran out of disk
 * space"), its disk kept.
 *
 * A STOPPED sandbox without volumes, its copy current, starts on another server when its own has
 * no room for it ({@link Sandboxes.resumeSandbox | resumeSandbox}), its addresses with it. If a
 * server is lost, each of its sandboxes with a copy is STOPPED from its last copy, saying when
 * that was if it ran since, and starts on another server at its next
 * {@link Sandboxes.resumeSandbox | resumeSandbox}; one without a copy is DELETED, as are its
 * volumes, which the sandboxes that mounted them lose. While nothing pays for its workspace
 * (Billing.suspended), its RUNNING and PAUSED sandboxes are STOPPED (UNPAID), and none of them
 * starts.
 */
export interface Sandbox {
  /** 16 characters, a-z and 0-9: also its DNS label. */
  sandboxId: string;
  state?: SandboxState | number;
  stateReason?: StateReason | number;
  /**
   * Prose for people whenever set: what failed, why it stopped or paused early, or what became of it
   * when its server was lost. Never parsed: stateReason is the fact.
   */
  stateMessage: string;
  /** When it entered its state. */
  stateTime?: Date;
  /** The exact version it started from: "my-app@3". */
  template: string;
  /** The sandbox it was copied from, if any. */
  forkedFrom: string;
  labels: Label[];
  /** In force: every group, its defaults filled in. */
  settings?: SandboxSettings;
  /** Grows with every change of its settings (UpdateSandboxRequest.ifRevision). */
  revision: bigint;
  /**
   * What it may write: its size's disk at its create, which a new size keeps unless growDisk grows
   * it to the new size's, and a fork its source's. No size whose disk is smaller is allowed (SIZES).
   */
  diskGib: number;
  mounts: Mount[];
  /** Its screen: every sandbox has one ({@link Sandboxes.controlDesktop | controlDesktop}). */
  desktop?: Desktop;
  /**
   * "ssh \<id>@\<server> -p 2222": signs in with a key of the workspace, or a
   * {@link Sandboxes.connectSandbox | connectSandbox} token as the password.
   */
  sshCommand: string;
  /**
   * Its page in the panel, where a person signs in to see its terminal, desktop and events. Give a
   * person this, not a link.
   */
  panelUrl: string;
  createTime?: Date;
  usage?: Usage;
  /**
   * In the answers of {@link Sandboxes.createSandbox | createSandbox} and
   * {@link Sandboxes.forkSandbox | forkSandbox} only: what
   * {@link Sandboxes.connectSandbox | connectSandbox} would answer. An MCP tool's answer leaves it
   * out: {@link Sandboxes.connectSandbox | connectSandbox} gives it to an agent that asks.
   */
  connection?: Connection;
  /**
   * STOPPED while its disk is fetched from object storage for a start: how far that is. Absent
   * otherwise.
   */
  restore?: Restore;
  /**
   * What its lifecycle makes of it next if nothing happens before (IDLE AND WAKE), and when: PAUSED,
   * STOPPED or DELETED. Absent while something keeps it awake, or when no timer of its lifecycle
   * runs in its state. {@link Sandboxes.getSandbox | getSandbox} only.
   */
  nextState?: SandboxState | number;
  nextStateTime?: Date;
  /**
   * PAUSED or STOPPED: what it holds of its own, as its server measured it when it entered its
   * state: PAUSED, its memory and its disk on its server; STOPPED, its disk, which object storage
   * keeps and Meter.STORED_GIB counts (USAGE).
   */
  storedBytes: bigint;
  /**
   * What people call it, if anything ({@link Sandboxes.createSandbox | createSandbox},
   * {@link Sandboxes.updateSandbox | updateSandbox}): unique among the workspace's sandboxes that
   * are not DELETED, and a DELETED one keeps it in its record. A call names a sandbox by sandboxId,
   * never by this: {@link Sandboxes.listSandboxes | listSandboxes} with `name` finds its id.
   */
  name: string;
}

