export const Sandbox: JsonCodec<Sandbox, Sandbox> = {
  toJson: (value) => writeJson(wire.SandboxSchema, convert.toSandbox(value)),
  fromJson: (json) => convert.fromSandbox(readJson(wire.SandboxSchema, json)),
};

