/**
 * What a sandbox has used so far, by the meters of USAGE: as its server counted it, up to the last
 * word the panel had from that server, some 10 seconds ago at most while it is in reach. One that
 * moved to another server counts from its move there; costMicros is what it was charged on every
 * server.
 *
 * Four meters (Meter), each priced at Workspace.billing's rates. A RUNNING sandbox counts its
 * size's seconds, each run rounded up to a whole second and 10 seconds at least, unless its server
 * ended it (out of memory or of disk space, its machine's restart, an unpaid workspace, a new
 * size), and a second counts at one size only. A PAUSED sandbox counts its size's seconds at its
 * paused price (SizeInfo.pausedHour, a share of runningHour), since its server keeps its place for
 * it; one paused for its server's restart counts nothing. A STOPPED sandbox counts the bytes of
 * its own its disk holds (Sandbox.storedBytes), which object storage keeps, never its empty space:
 * a long sleep costs least STOPPED. A volume counts its whole size. No other minimum: pausing and
 * waking never turns running time into a cheaper one, nor counts a second twice, since a stretch
 * counts from where the one before it was counted to (Sandbox.usage,
 * {@link Sandboxes.listUsage | listUsage}).
 */
export interface Usage {
  /** At every size, each run 10 seconds at least. */
  runningSeconds: bigint;
  /** At every size. */
  pausedSeconds: bigint;
  /** GiB held in object storage while STOPPED. */
  storedGibHours: number;
  /**
   * What it was charged so far, in millionths of the unit of Workspace.billing's currency. Absent
   * while its workspace is not billed.
   */
  costMicros: bigint;
}

/** {@link Usage} as the API's JSON, and back: {@link JsonCodec} says how. */
export const Usage: JsonCodec<Usage, Usage> = {
  toJson: (value) => writeJson(wire.UsageSchema, convert.toUsage(value)),
  fromJson: (json) => convert.fromUsage(readJson(wire.UsageSchema, json)),
};

