export type EnvVar = {
  /** DEBUG, ANTHROPIC_API_KEY */
  name: string;
} & (
  | {
      /**
       * Which of `value`, `secret` is set. `undefined` = none, or one this version of the SDK does not
       * know.
       */
      source: "value";
      value: string;
      secret?: undefined;
    }
  | {
      source: "secret";
      /**
       * A workspace secret's name ({@link Sandboxes.getWorkspace | getWorkspace} lists them): the
       * variable holds a placeholder, which the egress proxy swaps for the value in requests to the
       * secret's hosts. egress must allow them.
       */
      secret: string;
      value?: undefined;
    }
  | { source?: undefined; value?: undefined; secret?: undefined; }
);

export type EnvVarInput = {
  /** DEBUG, ANTHROPIC_API_KEY */
  name?: string | undefined;
} & (
  | {
      /** `source`: at most one of `value`, `secret`. */
      value?: string | undefined;
      secret?: undefined;
    }
  | {
      /**
       * A workspace secret's name ({@link Sandboxes.getWorkspace | getWorkspace} lists them): the
       * variable holds a placeholder, which the egress proxy swaps for the value in requests to the
       * secret's hosts. egress must allow them.
       *
       * `source`: at most one of `value`, `secret`.
       */
      secret?: string | undefined;
      value?: undefined;
    }
);

