export type SandboxEvent = {
  /** 16 digits: a later event's id is greater, compared as text or as a number. */
  eventId: string;
  time?: Date;
} & (
  | {
      /**
       * Which of `lifecycle`, `command`, `egress`, `port`, `agentTurn` is set. `undefined` = none, or
       * one this version of the SDK does not know.
       */
      event: "lifecycle";
      lifecycle: LifecycleEvent;
      command?: undefined;
      egress?: undefined;
      port?: undefined;
      agentTurn?: undefined;
    }
  | {
      event: "command";
      command: CommandEvent;
      lifecycle?: undefined;
      egress?: undefined;
      port?: undefined;
      agentTurn?: undefined;
    }
  | {
      event: "egress";
      egress: EgressEvent;
      lifecycle?: undefined;
      command?: undefined;
      port?: undefined;
      agentTurn?: undefined;
    }
  | {
      event: "port";
      port: PortEvent;
      lifecycle?: undefined;
      command?: undefined;
      egress?: undefined;
      agentTurn?: undefined;
    }
  | {
      event: "agentTurn";
      agentTurn: AgentTurnEvent;
      lifecycle?: undefined;
      command?: undefined;
      egress?: undefined;
      port?: undefined;
    }
  | { event?: undefined; lifecycle?: undefined; command?: undefined; egress?: undefined; port?: undefined; agentTurn?: undefined; }
);

