/**
 * One version of a template: ours, "base" (Ubuntu with build tools, Python, Node.js, the coding
 * agents, Docker and a desktop with Chrome, its version named by what it holds: base), or the
 * workspace's, a sandbox's disk saved over ours, shrunk to what it holds and kept in object
 * storage, which every server starts sandboxes from
 * ({@link Sandboxes.createTemplate | createTemplate}). A sandbox starts with no process of its
 * template's, and with its own hostname (its id), machine-id and randomness. Its desktop starts at
 * its first {@link Sandboxes.controlDesktop | controlDesktop} or desktop link (some seconds), and
 * Docker's daemon at the first connection to /var/run/docker.sock: neither costs anything until
 * then. Docker's images and containers are on the sandbox's disk, so a stop keeps them and a
 * template carries them.
 */
export interface Template {
  /** a-z, 0-9 and "-": "base", "my-app". */
  name: string;
  /** {@link Sandboxes.createSandbox | createSandbox} takes "my-app@3" for exactly this one. */
  version: number;
  state?: TemplateState | number;
  /** FAILED: what failed. */
  failureMessage: string;
  /** Ours, for every workspace. */
  builtIn: boolean;
  description: string;
  /** What its sandboxes get unless {@link Sandboxes.createSandbox | createSandbox} says. */
  settings?: SandboxSettings;
  createTime?: Date;
  /**
   * A workspace's READY version: what it takes in object storage, its own chunks compressed and
   * encrypted, what Limits.templateGib counts. 0 while SAVING, when FAILED, and for ours.
   */
  sizeBytes: bigint;
  /**
   * The version of our base its sandboxes start on, named by the sha256 of what it holds: the
   * operating system, its packages and the guest kernel. A version saved from a sandbox keeps the
   * base that sandbox started on, and a sandbox keeps its base for as long as it lives.
   */
  base: string;
  /**
   * A workspace's READY version: the smallest size whose disk holds what it saved. Its sandboxes
   * take any size from it up, the one it was saved from among them.
   */
  minSize?: Size | number;
}

/** {@link Template} as the API's JSON, and back: {@link JsonCodec} says how. */
export const Template: JsonCodec<Template, Template> = {
  toJson: (value) => writeJson(wire.TemplateSchema, convert.toTemplate(value)),
  fromJson: (json) => convert.fromTemplate(readJson(wire.TemplateSchema, json)),
};

