/** What an agent did, the same for every agent. */
export type AgentEvent = {
  /** 1, 2, 3, ... within the conversation. */
  seq: bigint;
  time?: Date;
  turnId: string;
} & (
  | {
      /**
       * Which of `prompt`, `message`, `toolCall`, `toolResult`, `turnEnd`, `caughtUp` is set.
       * `undefined` = none, or one this version of the SDK does not know.
       */
      event: "prompt";
      prompt: string;
      message?: undefined;
      toolCall?: undefined;
      toolResult?: undefined;
      turnEnd?: undefined;
      caughtUp?: undefined;
    }
  | {
      event: "message";
      /** Text it wrote: the first 64 KiB. */
      message: string;
      prompt?: undefined;
      toolCall?: undefined;
      toolResult?: undefined;
      turnEnd?: undefined;
      caughtUp?: undefined;
    }
  | {
      event: "toolCall";
      /** A command it ran, a file it read or edited, a search... */
      toolCall: ToolCall;
      prompt?: undefined;
      message?: undefined;
      toolResult?: undefined;
      turnEnd?: undefined;
      caughtUp?: undefined;
    }
  | {
      event: "toolResult";
      toolResult: ToolResult;
      prompt?: undefined;
      message?: undefined;
      toolCall?: undefined;
      turnEnd?: undefined;
      caughtUp?: undefined;
    }
  | {
      event: "turnEnd";
      /** The turn as it ended. */
      turnEnd: AgentTurn;
      prompt?: undefined;
      message?: undefined;
      toolCall?: undefined;
      toolResult?: undefined;
      caughtUp?: undefined;
    }
  | {
      event: "caughtUp";
      /**
       * {@link Sandboxes.watchConversation | watchConversation} only, once: the events before it were
       * there when the stream opened; what follows is live. Its seq is the last one sent, or afterSeq
       * when none was; or the conversation's last, when that is before afterSeq: a sandbox that lost its
       * memory may have lost its last events, and the next ones take their seq again.
       */
      caughtUp: CaughtUp;
      prompt?: undefined;
      message?: undefined;
      toolCall?: undefined;
      toolResult?: undefined;
      turnEnd?: undefined;
    }
  | { event?: undefined; prompt?: undefined; message?: undefined; toolCall?: undefined; toolResult?: undefined; turnEnd?: undefined; caughtUp?: undefined; }
);

/** {@link AgentEvent} as the API's JSON, and back: {@link JsonCodec} says how. */
